from pathlib import Path
from openpyxl import load_workbook
import zipfile
root=Path('/tmp/biomodstack-phase2-public')
keys=[f'BC{i}' for i in range(108,116)]
ws=load_workbook(root/'barcode_sequences.xlsx',read_only=True,data_only=True).active
allbc={str(r[0]).strip():str(r[1]).strip() for r in ws.iter_rows(min_row=3,values_only=True) if r[0]}
comp=str.maketrans('ACGT','TGCA'); bcs={k:(allbc[k],allbc[k].translate(comp)[::-1]) for k in keys}
handles={k:(root/f'{k}.supHAC.exact-barcode.fastq').open('wb') for k in keys}; counts={k:0 for k in keys}
with zipfile.ZipFile(root/'supHAC_data.zip') as z,z.open('supHAC.fastq') as f:
    while True:
        h=f.readline()
        if not h: break
        seq=f.readline(); plus=f.readline(); qual=f.readline(); edge=seq.decode().strip().upper(); edge=edge[:140]+edge[-140:]
        for k,(bc,rc) in bcs.items():
            if bc in edge or rc in edge:
                w=handles[k]; w.write(h);w.write(seq);w.write(plus);w.write(qual);counts[k]+=1
for w in handles.values(): w.close()

