from pathlib import Path
from openpyxl import load_workbook
import hashlib, zipfile, json
root=Path('/tmp/biomodstack-phase2-public')
records={}; name=None; parts=[]
for raw in (root/'Sanger_references.fasta').read_text().splitlines():
    line=raw.strip()
    if line.startswith('>'):
        if name: records[name]=''.join(parts).upper()
        name=line[1:]; parts=[]
    elif line: parts.append(line)
if name: records[name]=''.join(parts).upper()
ref_name='Gomphus_pulchellus_COI'; ref=records[ref_name]
(root/'BC115_Gomphus_pulchellus_COI.reference.fasta').write_text(f'>{ref_name}\n{ref}\n')
ws=load_workbook(root/'barcode_sequences.xlsx',read_only=True,data_only=True).active
barcodes={str(r[0]).strip():str(r[1]).strip() for r in ws.iter_rows(min_row=3,values_only=True) if r[0]}
bc=barcodes['BC115']; rc=bc.translate(str.maketrans('ACGT','TGCA'))[::-1]
out=root/'BC115.supHAC.exact-barcode.fastq'; count=0; source_total=0
with zipfile.ZipFile(root/'supHAC_data.zip') as z, z.open('supHAC.fastq') as f, out.open('wb') as w:
    while True:
        h=f.readline()
        if not h: break
        seq=f.readline(); plus=f.readline(); qual=f.readline(); source_total+=1
        s=seq.decode().strip().upper(); edge=s[:140]+s[-140:]
        if bc in edge or rc in edge:
            w.write(h); w.write(seq); w.write(plus); w.write(qual); count+=1
